def solve(n):
    """Return the number of primes strictly less than n (Sieve of Eratosthenes)."""
    if n <= 2:
        return 0
    sieve = bytearray([1]) * n
    sieve[0] = 0
    sieve[1] = 0
    i = 2
    while i * i < n:
        if sieve[i]:
            start = i * i
            sieve[start:n:i] = bytearray(len(range(start, n, i)))
        i += 1
    return sum(sieve)

