def solve(nums):
    # Find the first index from right where nums[i] < nums[i+1]
    n = len(nums)
    # Edge case empty or one element
    if n < 2:
        return sorted(nums)
    # Find pivot
    pivot = -1
    for i in range(n-2, -1, -1):
        if nums[i] < nums[i+1]:
            pivot = i
            break
    if pivot == -1:
        return sorted(nums)
    # Find rightmost successor greater than nums[pivot]
    for j in range(n-1, pivot, -1):
        if nums[j] > nums[pivot]:
            successor = j
            break
    # Create new list to avoid mutating input
    res = list(nums)
    # Swap pivot and successor
    res[pivot], res[successor] = res[successor], res[pivot]
    # Reverse suffix after pivot
    res[pivot+1:] = reversed(res[pivot+1:])
    return res

