def solve(tokens):
    """Evaluate Reverse Polish Notation expression.
    tokens: list of strings, each token is an integer or one of '+', '-', '*', '/'.
    Division truncates toward zero as specified.
    Returns the integer result.
    """
    stack = []
    for tok in tokens:
        if tok in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                stack.append(a + b)
            elif tok == '-':
                stack.append(a - b)
            elif tok == '*':
                stack.append(a * b)
            else:  # division
                # Python's // floor division truncates toward -inf; need truncation toward 0
                if a * b < 0:
                    stack.append(-(abs(a) // abs(b)))
                else:
                    stack.append(a // b)
        else:
            stack.append(int(tok))
    return stack[0] if stack else 0

