def solve(path):
    """Simplify an absolute Unix path.
    Resolve '.' and '..', collapse multiple slashes, and remove any trailing slash.
    The result always starts with '/' (unless the input is empty, in which case return an empty string).
    """
    # Edge case: empty input
    if not path:
        return ""
    parts = path.split('/')
    stack = []
    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
            # If stack empty, stay at root (do nothing)
        else:
            stack.append(part)
    # Construct result
    return '/' + '/'.join(stack)

