def solve(line):
    fields=[]
    i=0
    n=len(line)
    while i<=n:
        # start field
        if i==n:
            # reached end after last comma, add empty field
            fields.append('')
            break
        if line[i]=='"':
            # quoted field
            i+=1
            field_chars=[]
            while i<n:
                if line[i]=='"':
                    # possible end or escaped quote
                    if i+1<n and line[i+1]=='"':
                        field_chars.append('"')
                        i+=2
                        continue
                    else:
                        i+=1
                        break
                else:
                    field_chars.append(line[i])
                    i+=1
            # after closing quote, expect comma or end
            while i<n and line[i]!=',':
                # skip any chars until comma? but per spec probably none
                i+=1
            fields.append(''.join(field_chars))
            if i<n and line[i]==',':
                i+=1
                continue
            else:
                # end of line
                if i==n:
                    break
        else:
            # unquoted field
            field_chars=[]
            while i<n and line[i]!=',':
                field_chars.append(line[i])
                i+=1
            fields.append(''.join(field_chars))
            if i<n and line[i]==',':
                i+=1
                continue
            else:
                break
    return fields

