def solve(n, b):
    """Convert integer n to its representation in base b (2-36).
    Uses digits 0-9 and a-z for values 10-35. Handles negative numbers.
    """
    if not (2 <= b <= 36):
        raise ValueError('Base must be between 2 and 36')
    digits = '0123456789abcdefghijklmnopqrstuvwxyz'
    if n == 0:
        return '0'
    sign = '-' if n < 0 else ''
    n = abs(n)
    res = []
    while n:
        n, r = divmod(n, b)
        res.append(digits[r])
    return sign + ''.join(reversed(res))

