def solve(a,b):
    # classic DP Levenshtein distance
    m,n=len(a),len(b)
    # ensure shorter dimension for memory
    if m< n:
        # swap so that n is smaller? but fine
        pass
    dp=[[0]*(n+1) for _ in range(m+1)]
    for i in range(m+1):
        dp[i][0]=i
    for j in range(n+1):
        dp[0][j]=j
    for i in range(1,m+1):
        for j in range(1,n+1):
            if a[i-1]==b[j-1]:
                cost=0
            else:
                cost=1
