def solve(meetings):
    # Greedy: select meetings with earliest end time
    if not meetings:
        return 0
    # sort by end, then start for consistency
    meetings_sorted = sorted(meetings, key=lambda x: (x[1], x[0]))
    count = 0
    last_end = -float('inf')
    for start, end in meetings_sorted:
        if start >= last_end:
            count += 1
            last_end = end
    return count
